/** The budget the explorer's builder declares (`exploration_chat@2`). */
export const BUDGET = { messages: 12_000, decisions: 4_000, sources: 6_000, knowledge: 4_000 } as const;

type Source = Manifest['fragments'][number]['source'];
const source = (type: string, id: string, version: number | null = null, eventSeq: number | null = null): Source => ({
  type,
  id,
  version,
  eventSeq,
});

const DECISION_TITLE_CHARS = 8;

